CREATE OR REPLACE FUNCTION get_driver_age(p_drv_main INTEGER)
RETURNS INTEGER AS $$
DECLARE
    v_birth_date DATE;
BEGIN
    SELECT (driver_identity->>'birth_date')::DATE INTO v_birth_date
    FROM drivers
    WHERE drv_main = p_drv_main;

    IF v_birth_date IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN FLOOR(EXTRACT(EPOCH FROM (CURRENT_DATE - v_birth_date)) / (365.25 * 24 * 60 * 60))::INTEGER;
END;
$$ LANGUAGE plpgsql;

